<script lang="ts">
  import { ArrowLeft, ArrowUpRight, Check, Edit3, Link, Pencil, Plus, Save, Trash2, X } from '@lucide/svelte';
  import { onMount } from 'svelte';
  import { profileSchema } from '$lib/schemas';
  import { byuiMajors, graduationYears, interestOptions, skillOptions } from '$lib/profile-options';
  import type { PageData } from './$types';

  type ProfileLink = { label: string; url: string };
  type PreviousProject = { title: string; description: string; url: string };
  export let data: PageData;
  let editing = false, saved = false, pending = false, error = '';
  let firstName = data.user?.firstName ?? '', lastName = data.user?.lastName ?? '';
  let major = data.user?.major ?? '', graduationYear = data.user?.graduationYear?.toString() ?? '2026';
  let bio = data.user?.bio ?? '', skills: string[] = data.user?.skills ?? [], interests: string[] = data.user?.interests ?? [];
  let links: ProfileLink[] = (data.user?.links ?? []) as ProfileLink[];
  let previousProjects: PreviousProject[] = (data.user?.previousProjects ?? []) as PreviousProject[];
  let avatarUrl: string | null = data.user?.avatarUrl ?? null, selectedSkill = '', selectedInterest = '';

  onMount(() => document.querySelector('.profile-page')?.setAttribute('data-app-ready', 'true'));
  $: initials = `${firstName[0] ?? '?'}${lastName[0] ?? ''}`.toUpperCase();
  function addSkill() { const skill = selectedSkill.trim(); if (skill && !skills.includes(skill) && skills.length < 30) skills = [...skills, skill]; selectedSkill = ''; }
  function removeSkill(skill: string) { skills = skills.filter((item) => item !== skill); }
  function addInterest() { const interest = selectedInterest.trim(); if (interest && !interests.includes(interest) && interests.length < 20) interests = [...interests, interest]; selectedInterest = ''; }
  function removeInterest(interest: string) { interests = interests.filter((item) => item !== interest); }
  function addLink() { if (links.length < 8) links = [...links, { label: '', url: '' }]; }
  function removeLink(index: number) { links = links.filter((_, linkIndex) => linkIndex !== index); }
  function addPreviousProject() { if (previousProjects.length < 8) previousProjects = [...previousProjects, { title: '', description: '', url: '' }]; }
  function removePreviousProject(index: number) { previousProjects = previousProjects.filter((_, projectIndex) => projectIndex !== index); }
  function editProfileSection() { editing = true; saved = false; error = ''; }
  function handleAvatar(event: Event) {
    const file = (event.currentTarget as HTMLInputElement).files?.[0]; if (!file) return;
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) { error = 'Choose a JPG, PNG, or WebP image.'; return; }
    if (file.size > 2_000_000) { error = 'Your image must be smaller than 2 MB.'; return; }
    const reader = new FileReader(); reader.onload = () => { avatarUrl = typeof reader.result === 'string' ? reader.result : null; }; reader.readAsDataURL(file);
  }
  async function saveProfile() {
    const result = profileSchema.safeParse({ firstName, lastName, major, graduationYear, bio, skills, interests, links, previousProjects, avatarUrl });
    if (!result.success) { error = result.error.issues[0]?.message ?? 'Please check your profile details.'; saved = false; return; }
    pending = true; error = '';
    try {
      const response = await fetch('/api/profile', { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify(result.data) });
      const payload = await response.json(); if (!response.ok) throw new Error(payload.message ?? 'Could not save your profile.');
      saved = true; editing = false;
    } catch (saveError) { saved = false; error = saveError instanceof Error ? saveError.message : 'Could not save your profile.'; } finally { pending = false; }
  }
</script>

<svelte:head><title>Profile — BuildTogether</title><meta name="description" content="Your BuildTogether student profile." /></svelte:head>
<div class="profile-page">
  <header class="profile-header"><a class="brand" href="/" aria-label="BuildTogether home"><span class="brand-mark brand-image"><img src="/brand/handshake-emblem.png" alt="" /></span><span>Build<span>Together</span></span></a><div class="profile-header-actions"><a href="/"><ArrowLeft size={15} /> Discover projects</a><span class="profile-avatar small">{initials}</span></div></header>
  <main class="profile-main">
    <div class="profile-topline"><div><p class="eyebrow">Your student profile</p><h1>Make your work easy to find.</h1><p>Share what you’re learning, what you care about, and where you want to contribute.</p></div><button class="button button-dark" type="button" onclick={() => { editing = !editing; saved = false; error = ''; }}>{#if editing}<X size={15} /> Cancel{:else}<Edit3 size={15} /> Edit profile{/if}</button></div>
    {#if saved}<div class="save-notice" role="status"><Check size={15} /> Profile saved.</div>{/if}
    <div class="profile-grid">
      <section class="profile-card profile-summary"><button class="section-edit" type="button" aria-label="Edit profile photo and links" onclick={editProfileSection}><Pencil size={14} /></button>{#if avatarUrl}<img class="profile-avatar-image" src={avatarUrl} alt="{firstName} {lastName}" />{:else}<div class="profile-avatar large">{initials}</div>{/if}<h2>{firstName || 'Complete your profile'} {lastName}</h2><p>{major || 'Add your major'} · Class of {graduationYear}</p><span class="verified-chip"><Check size={12} /> BYU-Idaho student</span><div class="summary-links">{#if links.length > 0}{#each links as link}<a href={link.url} target="_blank" rel="noreferrer"><Link size={15} /> {link.label}<ArrowUpRight size={12} /></a>{/each}{:else}<span class="empty-links">Add links to your work.</span>{/if}</div></section>
      <section class="profile-card profile-details">
        {#if editing}
          <div class="card-heading"><div><p class="eyebrow">Edit your details</p><h2>Make this profile yours.</h2></div><Save size={19} color="var(--byui-blue)" /></div>
          <form onsubmit={(event) => { event.preventDefault(); saveProfile(); }}>
            <div class="photo-field"><div>{#if avatarUrl}<img class="profile-avatar preview" src={avatarUrl} alt="Profile preview" />{:else}<div class="profile-avatar preview">{initials}</div>{/if}</div><label>Profile image<input type="file" accept="image/jpeg,image/png,image/webp" onchange={handleAvatar} /><small>JPG, PNG, or WebP · 2 MB maximum</small></label>{#if avatarUrl}<button class="text-button" type="button" onclick={() => avatarUrl = null}>Remove image</button>{/if}</div>
            <div class="field-row"><label>First name<input aria-label="First name" bind:value={firstName} /></label><label>Last name<input aria-label="Last name" bind:value={lastName} /></label></div>
            <div class="field-row"><label>Major<select aria-label="Major" bind:value={major}><option value="" disabled>Select your major</option>{#each byuiMajors as option}<option value={option}>{option}</option>{/each}</select></label><label>Graduation year<select aria-label="Graduation year" bind:value={graduationYear}>{#each graduationYears as year}<option value={year}>{year}</option>{/each}</select></label></div>
            <label>Short bio<textarea aria-label="Short bio" bind:value={bio} rows="4" maxlength="280" placeholder="Tell collaborators what you care about."></textarea><small class="field-hint">{bio.length}/280</small></label>
            <div class="editor-section"><div class="section-heading"><div><p class="eyebrow">Skills</p><h3>What can you bring?</h3></div></div><div class="skill-editor">{#each skills as skill}<button class="skill-chip" type="button" onclick={() => removeSkill(skill)}>{skill}<X size={12} /></button>{/each}</div><div class="add-row"><select aria-label="Add a skill" bind:value={selectedSkill}><option value="">Select a skill</option>{#each skillOptions as option}<option value={option}>{option}</option>{/each}</select><button class="button button-outline button-small" type="button" onclick={addSkill}><Plus size={14} /> Add skill</button></div><label class="custom-skill">Custom skill<input placeholder="Or type your own skill" onkeydown={(event) => { if (event.key === 'Enter') { event.preventDefault(); const input = event.currentTarget as HTMLInputElement; if (input.value.trim() && !skills.includes(input.value.trim())) skills = [...skills, input.value.trim()]; input.value = ''; } }} /></label></div>
            <div class="editor-section"><div class="section-heading"><div><p class="eyebrow">Links</p><h3>Point people to your work.</h3></div><button class="icon-action" type="button" aria-label="Add link" onclick={addLink}><Plus size={17} /></button></div>{#each links as link, index}<div class="link-editor"><input aria-label="Link label {index + 1}" placeholder="GitHub, portfolio, LinkedIn" bind:value={link.label} /><input aria-label="Link URL {index + 1}" placeholder="https://example.com" bind:value={link.url} /><button class="remove-button" type="button" aria-label="Remove link {index + 1}" onclick={() => removeLink(index)}><Trash2 size={15} /></button></div>{/each}{#if links.length === 0}<p class="muted-note">No links added yet.</p>{/if}</div>
            <div class="editor-section"><div class="section-heading"><div><p class="eyebrow">Previous projects</p><h3>Show what you’ve built before.</h3></div><button class="icon-action" type="button" aria-label="Add previous project" onclick={addPreviousProject}><Plus size={17} /></button></div>{#each previousProjects as project, index}<div class="previous-project-editor"><input aria-label="Previous project title {index + 1}" placeholder="Project title" bind:value={project.title} /><textarea aria-label="Previous project description {index + 1}" rows="2" maxlength="280" placeholder="What did you build or learn?" bind:value={project.description}></textarea><input aria-label="Previous project URL {index + 1}" placeholder="https://example.com (optional)" bind:value={project.url} /><button class="remove-button" type="button" aria-label="Remove previous project {index + 1}" onclick={() => removePreviousProject(index)}><Trash2 size={15} /></button></div>{/each}{#if previousProjects.length === 0}<p class="muted-note">Add personal, school, work, or community projects from outside BuildTogether.</p>{/if}</div>
            {#if error}<p class="form-error" role="alert">{error}</p>{/if}<button class="button button-dark" type="submit" disabled={pending}>{pending ? 'Saving…' : 'Save profile'} <Check size={15} /></button>
            <div class="editor-section"><div class="section-heading"><div><p class="eyebrow">Interests</p><h3>What topics matter to you?</h3></div></div><div class="skill-editor">{#each interests as interest}<button class="skill-chip interest-chip" type="button" onclick={() => removeInterest(interest)}>{interest}<X size={12} /></button>{/each}</div><div class="add-row"><select aria-label="Add an interest" bind:value={selectedInterest}><option value="">Select an interest</option>{#each interestOptions as option}<option value={option}>{option}</option>{/each}</select><button class="button button-outline button-small" type="button" onclick={addInterest}><Plus size={14} /> Add interest</button></div></div>
          </form>
        {:else}
          <div class="card-heading"><div><p class="eyebrow">About {firstName || 'you'}</p><h2>A little context goes a long way.</h2></div><div class="heading-actions"><button class="section-edit inline" type="button" aria-label="Edit details" onclick={editProfileSection}><Pencil size={14} /></button><span class="completion">{Math.min(100, Math.round(([firstName, lastName, major, bio, skills.length > 0 ? 'skills' : '', links.length > 0 ? 'links' : '', avatarUrl ? 'photo' : '', previousProjects.length > 0 ? 'projects' : ''].filter(Boolean).length / 8) * 100))}% complete</span></div></div><p class="bio">{bio || 'Add a short bio to help collaborators get to know you.'}</p><div class="details-divider"></div><div class="details-row"><span>Major</span><strong>{major || 'Not added yet'}</strong></div><div class="details-row"><span>Graduation year</span><strong>{graduationYear}</strong></div>
        {/if}
      </section>
      <section class="profile-card skills-card"><div class="card-heading"><div><p class="eyebrow">Skills</p><h2>What I can bring.</h2></div><button class="section-edit inline" type="button" aria-label="Edit skills" onclick={editProfileSection}><Pencil size={14} /></button></div><div class="skill-list">{#if skills.length > 0}{#each skills as skill}<span>{skill}</span>{/each}{:else}<p class="muted-note">Add skills to show collaborators what you can bring.</p>{/if}</div><p class="muted-note">Skills are self-reported until you have verified contributions.</p></section>
      <section class="profile-card previous-projects-card"><div class="card-heading"><div><p class="eyebrow">Previous projects</p><h2>What you’ve built before.</h2></div><button class="section-edit inline" type="button" aria-label="Edit previous projects" onclick={editProfileSection}><Pencil size={14} /></button></div>{#if previousProjects.length > 0}<div class="previous-project-list">{#each previousProjects as project}<article class="previous-project"><div><h3>{project.title}</h3><p>{project.description}</p></div>{#if project.url}<a href={project.url} target="_blank" rel="noreferrer" aria-label="Open {project.title}"><ArrowUpRight size={15} /></a>{/if}</article>{/each}</div>{:else}<div class="empty-previous"><p>No previous projects yet.</p><span>Personal projects, class assignments, work, and community projects all count.</span></div>{/if}</section>
      <section class="profile-card activity-card"><div class="card-heading"><div><p class="eyebrow">Activity</p><h2>My BuildTogether trail.</h2></div></div><div class="empty-activity"><span><Plus size={17} /></span><div><strong>No projects yet.</strong><p>Apply to a project or start your own to begin building your profile.</p><a href="/#projects">Explore projects <ArrowUpRight size={13} /></a></div></div></section>
    </div>
  </main>
</div>

<style>
  .profile-page{min-height:100vh;background:#f6fbff;color:#000;font-family:var(--byui-body)}.profile-header{height:78px;padding:0 clamp(20px,6vw,80px);display:flex;justify-content:space-between;align-items:center;background:#fff;border-bottom:1px solid rgba(148,149,152,.3)}.profile-header .brand{text-decoration:none}.profile-header .brand-image{width:46px;height:31px}.profile-header-actions{display:flex;align-items:center;gap:22px}.profile-header-actions>a{display:flex;align-items:center;gap:7px;color:var(--byui-deep-blue);font:700 12px var(--byui-display);text-decoration:none}.profile-avatar{display:grid;place-items:center;border-radius:50%;background:var(--byui-light-blue);color:var(--byui-deep-blue);font:800 12px var(--byui-display);object-fit:cover}.profile-avatar.small{width:34px;height:34px}.profile-avatar.large{width:82px;height:82px;font-size:25px;margin:0 auto 18px}.profile-avatar-image{width:82px;height:82px;border-radius:50%;object-fit:cover;margin:0 auto 18px;display:block}.profile-avatar.preview{width:58px;height:58px;font-size:17px}.profile-main{max-width:1160px;margin:auto;padding:68px clamp(20px,6vw,80px) 90px}.profile-topline{display:flex;justify-content:space-between;align-items:end;gap:25px;margin-bottom:32px}.profile-topline h1{margin:0;color:#000;font:700 clamp(38px,5vw,58px)/.98 var(--byui-display);letter-spacing:-.055em}.profile-topline>div>p:last-child{color:#53656b;font-size:13px;margin:13px 0 0}.profile-grid{display:grid;grid-template-columns:280px 1fr;gap:16px}.profile-card{background:#fff;border:1px solid rgba(148,149,152,.35);border-radius:11px;padding:25px}.profile-summary{text-align:center}.profile-summary h2,.profile-details h2,.skills-card h2,.activity-card h2{color:#000;font:700 22px var(--byui-display);letter-spacing:-.035em;margin:0}.profile-summary>p{color:#65767b;font-size:12px;margin:8px 0 12px}.verified-chip{display:inline-flex;align-items:center;gap:5px;padding:6px 9px;background:var(--byui-light-blue);color:var(--byui-deep-blue);border-radius:99px;font:700 10px var(--byui-display)}.summary-links{border-top:1px solid #dfe6e8;margin-top:25px;padding-top:17px;display:grid;gap:12px;text-align:left}.summary-links a{display:flex;align-items:center;gap:7px;color:var(--byui-deep-blue);font:11px var(--byui-display);text-decoration:none}.summary-links a :global(svg:last-child){margin-left:auto}.empty-links{color:#8b989c;font-size:11px}.profile-details{grid-column:2}.card-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.card-heading .eyebrow{margin-bottom:8px}.completion{color:var(--byui-blue);font:700 10px var(--byui-display);padding-top:5px}.bio{color:#394a50;line-height:1.65;font-size:14px;max-width:590px;margin:23px 0}.details-divider{border-top:1px solid #dfe6e8;margin:20px 0 0}.details-row{display:flex;justify-content:space-between;gap:20px;padding:13px 0;border-bottom:1px solid #edf1f2;color:#819095;font-size:12px}.details-row strong{color:#1a303a;font-family:var(--byui-display)}.skills-card{grid-column:1}.skill-list{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0 15px}.skill-list span,.skill-chip{display:inline-flex;align-items:center;gap:5px;padding:8px 10px;background:#e8f4fb;color:var(--byui-deep-blue);border-radius:5px;font:700 11px var(--byui-display)}.muted-note{color:#879296;font-size:10px;line-height:1.5;margin:0}.icon-action{width:30px;height:30px;display:grid;place-items:center;border:1px solid #c8d9df;background:#fff;color:var(--byui-blue);border-radius:6px}.activity-card{grid-column:2}.empty-activity{border-top:1px solid #dfe6e8;margin-top:20px;padding-top:22px;display:flex;align-items:flex-start;gap:12px}.empty-activity>span{width:30px;height:30px;display:grid;place-items:center;background:var(--byui-light-blue);color:var(--byui-deep-blue);border-radius:50%}.empty-activity strong{font:700 12px var(--byui-display)}.empty-activity p{color:#687579;font-size:11px;line-height:1.5;margin:6px 0}.empty-activity a{display:inline-flex;align-items:center;gap:5px;color:var(--byui-blue);font:700 10px var(--byui-display);text-decoration:none}.profile-card form{display:grid;gap:14px;margin-top:25px}.field-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.profile-card label{display:grid;gap:6px;color:var(--byui-deep-blue);font:700 11px var(--byui-display)}.profile-card input,.profile-card textarea,.profile-card select{border:1px solid #c9d8df;border-radius:6px;padding:10px;color:#000;background:#fff;outline:0;font:14px var(--byui-body)}.profile-card input:focus,.profile-card textarea:focus,.profile-card select:focus{border-color:var(--byui-blue);box-shadow:0 0 0 3px rgba(0,110,182,.14)}.profile-card small{color:#829197;font:10px var(--byui-body)}.form-error{color:#a32626;font:11px var(--byui-display);margin:0}.save-notice{display:flex;align-items:center;gap:7px;color:var(--byui-deep-blue);background:var(--byui-light-blue);padding:10px 13px;border-radius:6px;font:700 11px var(--byui-display);margin:-15px 0 22px}.profile-topline .button{font-family:var(--byui-display)}.photo-field{display:flex;align-items:center;gap:12px;padding-bottom:14px;border-bottom:1px solid #edf1f2}.photo-field>div{flex:0 0 auto}.photo-field label{flex:1}.text-button{border:0;background:transparent;color:var(--byui-blue);font:700 10px var(--byui-display);cursor:pointer}.editor-section{border-top:1px solid #dfe6e8;padding-top:17px;margin-top:3px}.section-heading{display:flex;justify-content:space-between;align-items:center}.section-heading h3{font:700 15px var(--byui-display);margin:0}.skill-editor{display:flex;flex-wrap:wrap;gap:7px;margin:14px 0}.skill-chip{border:0;cursor:pointer}.add-row{display:flex;gap:8px}.add-row select{flex:1}.button-small{font-size:10px!important;padding:8px 10px!important}.custom-skill{margin-top:10px}.link-editor{display:grid;grid-template-columns:.55fr 1fr 30px;gap:7px;margin-top:10px}.remove-button{border:1px solid #e0c6c6;background:#fff;color:#a32626;border-radius:6px;display:grid;place-items:center}.field-hint{display:block;text-align:right}.profile-card .button{cursor:pointer}.profile-card .button:disabled{opacity:.6;cursor:wait}
  @media(max-width:780px){.profile-header-actions>a{display:none}.profile-main{padding-top:48px}.profile-topline{align-items:flex-start;flex-direction:column}.profile-grid{grid-template-columns:1fr}.profile-details,.skills-card,.activity-card{grid-column:auto}.field-row,.link-editor{grid-template-columns:1fr}.add-row{align-items:stretch;flex-direction:column}}
  .profile-summary{position:relative}.section-edit{border:0;background:transparent;color:#6f858e;display:grid;place-items:center;padding:5px;cursor:pointer}.section-edit:hover{color:var(--byui-blue);background:var(--byui-light-blue);border-radius:5px}.profile-summary>.section-edit{position:absolute;top:17px;right:17px}.heading-actions{display:flex;align-items:flex-start;gap:8px}.previous-projects-card{grid-column:1 / -1}.previous-project-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:20px}.previous-project{display:flex;justify-content:space-between;gap:14px;border:1px solid #e0e9eb;border-radius:7px;padding:14px;background:#fbfdfe}.previous-project h3{color:var(--byui-deep-blue);font:700 14px var(--byui-display);margin:0 0 6px}.previous-project p{color:#65767b;font-size:11px;line-height:1.5;margin:0}.previous-project a{color:var(--byui-blue);display:grid;place-items:center}.empty-previous{border-top:1px solid #dfe6e8;margin-top:20px;padding-top:20px}.empty-previous p{color:var(--byui-deep-blue);font:700 12px var(--byui-display);margin:0 0 6px}.empty-previous span{color:#879296;font-size:11px}.previous-project-editor{display:grid;grid-template-columns:1fr 30px;gap:8px;margin-top:10px}.previous-project-editor textarea{grid-column:1 / -1;resize:vertical}.previous-project-editor input:nth-of-type(2){grid-column:1 / -1}.previous-project-editor .remove-button{grid-column:2;grid-row:1;min-height:30px}
  .previous-projects-card{grid-column:2}.previous-projects-card h2{color:#000;font:700 22px var(--byui-display);letter-spacing:-.035em;margin:0}.activity-card{grid-column:1 / -1}
  @media(max-width:780px){.previous-projects-card,.activity-card{grid-column:auto}.previous-project-list{grid-template-columns:1fr}.previous-project-editor{grid-template-columns:1fr}.previous-project-editor .remove-button{grid-column:auto;grid-row:auto;min-height:34px}}
</style>
